
const STORAGE_KEY = "freshsave-foods-v5";

const LEGACY_STORAGE_KEYS = [
  "freshsave-foods-v5",
  "freshsave-foods-v4",
  "freshsave-foods-v3",
  "freshsave-foods-v2",
  "freshsave-foods"
];

function migrateLegacyFoods() {
  const current = JSON.parse(localStorage.getItem(STORAGE_KEY) || "null");
  if (Array.isArray(current) && current.length) return current;
  for (const key of LEGACY_STORAGE_KEYS) {
    try {
      const raw = localStorage.getItem(key);
      if (!raw) continue;
      const data = JSON.parse(raw);
      if (Array.isArray(data) && data.length) {
        const normalized = data.map((item, idx) => ({
          id: item.id || Date.now() + idx,
          name: canonicalName(item.name || item.foodName || ""),
          expiryDate: item.expiryDate || item.date || "",
          category: item.category || guessCategory(item.name || item.foodName || "")
        })).filter(item => item.name && item.expiryDate);
        if (normalized.length) {
          localStorage.setItem(STORAGE_KEY, JSON.stringify(normalized));
          return normalized;
        }
      }
    } catch (e) {}
  }
  return [];
}

